overflow:hidden;}.ds-mkt-pop-left{width:540px;flex-shrink:0;background:#0d1424;display:flex;flex-direction:column;padding:20px;}.ds-mkt-pop-img{flex:1;border-radius:12px;overflow:hidden;background:#080a10;display:flex;align-items:center;justify-content:center;min-height:320px;border:1px solid #1e2a40;position:relative;}.ds-mkt-pop-img img{width:100%;height:100%;object-fit:contain;display:block;max-height:420px;cursor:zoom-in;transition:transform .2s;}.ds-mkt-pop-thumbs{display:flex;gap:6px;margin-top:10px;overflow-x:auto;padding-bottom:4px;}.ds-mkt-pop-thumb{width:56px;height:42px;border-radius:6px;overflow:hidden;cursor:pointer;border:2px solid transparent;flex-shrink:0;}.ds-mkt-pop-thumb.active,.ds-mkt-pop-thumb:hover{border-color:#3b82f6;}.ds-mkt-pop-thumb img{width:100%;height:100%;object-fit:cover;}.ds-mkt-pop-right{flex:1;padding:24px;overflow-y:auto;display:flex;flex-direction:column;}.ds-mkt-pop-cat{font-size:11px;font-weight:600;color:#60a5fa;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;}.ds-mkt-pop-title{font-size:20px;font-weight:800;color:#f1f5f9;margin:0 0 6px;}.ds-mkt-pop-by{font-size:12px;color:#64748b;margin:0 0 12px;}.ds-mkt-pop-desc{font-size:13px;color:#94a3b8;line-height:1.7;margin:0 0 16px;flex:1;}.ds-mkt-pop-meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:20px;padding:14px;background:#0d1424;border-radius:10px;border:1px solid #1e2a40;}.ds-meta-lbl{display:block;font-size:10px;font-weight:700;color:#4a6080;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px;}.ds-meta-val{font-size:13px;font-weight:600;color:#94a3b8;}.ds-mkt-pop-dl{display:block;width:100%;padding:13px;border-radius:10px;background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;text-align:center;font-size:14px;font-weight:700;text-decoration:none;border:none;cursor:pointer;transition:all .15s;margin-bottom:8px;box-sizing:border-box;font-family:inherit;}.ds-mkt-pop-dl:hover{background:linear-gradient(135deg,#1d4ed8,#1e40af);}.ds-mkt-pop-dl.locked{background:#1e2d4a;color:#64748b;}.ds-mkt-pop-share{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:12px;border-radius:10px;background:#7c3aed;color:#fff;text-align:center;font-size:13px;font-weight:700;border:none;cursor:pointer;transition:all .15s;margin-bottom:8px;box-sizing:border-box;font-family:inherit;}.ds-mkt-pop-share:hover{background:#6d28d9;}.ds-mkt-pop-close{display:flex;align-items:center;justify-content:center;gap:6px;width:100%;padding:10px;border-radius:10px;border:1.5px solid #2d3a55;background:transparent;color:#64748b;font-size:13px;font-weight:600;cursor:pointer;box-sizing:border-box;font-family:inherit;}/* Share modal */ .ds-mkt-share-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.75);z-index:999999;align-items:center;justify-content:center;}.ds-mkt-share-overlay.open{display:flex;}.ds-mkt-share-box{background:#1a1a2e;border-radius:18px;padding:24px;max-width:360px;width:90%;box-shadow:0 20px 60px rgba(0,0,0,.5);border:1px solid #2d3a55;}.ds-mkt-share-box h3{font-size:15px;font-weight:800;color:#f1f5f9;margin:0 0 4px;}.ds-mkt-share-box p{font-size:12px;color:#64748b;margin:0 0 14px;}.ds-mkt-share-preview-wrap{position:relative;margin-bottom:14px;}.ds-mkt-share-preview-wrap img{width:100%;border-radius:10px;max-height:180px;object-fit:cover;background:#0d1424;display:block;}.ds-mkt-share-overlay-text{position:absolute;bottom:0;left:0;right:0;background:linear-gradient(transparent,rgba(0,0,0,.75));padding:10px 12px;border-radius:0 0 10px 10px;}.ds-mkt-share-overlay-title{font-size:12px;color:#fff;font-weight:600;}.ds-mkt-share-card{background:linear-gradient(135deg,#0f1f3d,#1e1040);border-radius:10px;padding:12px 14px;margin-bottom:14px;}.ds-mkt-share-card-title{font-size:14px;font-weight:800;color:#fff;margin-bottom:3px;}.ds-mkt-share-card-sub{font-size:11px;color:rgba(255,255,255,.4);}.ds-mkt-share-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:1